// RAG Ingestion — Documents are injected via the companion script.
// This node processes the injected documents array.
// The script writes documents to n8n's static data before triggering.

// Get documents from the input (injected by the companion ingest script)
const input = $input.first();

// If no documents provided, use placeholder for testing
const documents = [
  {
    title: 'Crypto Market Fundamentals - Bitcoin Halving 2024',
    content: 'The Bitcoin halving event in April 2024 reduced block rewards from 6.25 BTC to 3.125 BTC. Historically, halvings have preceded bull runs within 12-18 months. The reduced supply issuance combined with growing institutional demand from spot ETFs creates potential supply shock dynamics. Previous halvings in 2012, 2016, and 2020 all preceded significant price appreciation.',
    source: 'rag_knowledge_base',
    category: 'fundamentals'
  },
  {
    title: 'Ethereum Layer 2 Ecosystem Growth',
    content: 'Ethereum Layer 2 solutions (Arbitrum, Optimism, Base, zkSync) have collectively surpassed $30B in TVL. The Dencun upgrade introducing EIP-4844 (Proto-Danksharding) reduced L2 transaction costs by 90-99%. This has accelerated DeFi migration to L2s and is expected to drive ETH demand through data availability fees.',
    source: 'rag_knowledge_base',
    category: 'ecosystem'
  },
  {
    title: 'Solana DeFi and Memecoin Activity',
    content: 'Solana has seen explosive growth in DeFi TVL and memecoin trading volume. Jupiter DEX aggregator processes over $1B daily volume. The Solana network handles 2000+ TPS consistently. Key risk factors include periodic network congestion during high-activity memecoin launches and validator centralization concerns.',
    source: 'rag_knowledge_base',
    category: 'ecosystem'
  },
  {
    title: 'Crypto Regulation Landscape 2024-2025',
    content: 'The SEC approved 11 spot Bitcoin ETFs in January 2024, with cumulative inflows exceeding $50B. MiCA regulation in the EU went into effect in December 2024, providing regulatory clarity for stablecoins and crypto asset service providers. Hong Kong and Singapore continue competing for crypto hub status with progressive licensing frameworks.',
    source: 'rag_knowledge_base',
    category: 'regulation'
  },
  {
    title: 'Stablecoin Market Dynamics',
    content: 'USDT market cap exceeds $110B, USDC at $32B. Stablecoin transaction volume surpasses Visa annually. Key risks include de-peg events (as seen with UST in 2022), regulatory crackdowns on unbacked stablecoins, and banking relationship risks. Circle USDC maintains full reserves in US Treasuries and cash.',
    source: 'rag_knowledge_base',
    category: 'market_structure'
  },
  {
    title: 'Institutional Crypto Adoption Trends',
    content: 'BlackRock, Fidelity, and other major asset managers now offer spot crypto ETFs. Traditional finance institutions including JPMorgan, Goldman Sachs, and Morgan Stanley provide crypto exposure to clients. Corporate treasury adoption beyond MicroStrategy includes Tesla, Block, and multiple mining companies. Pension funds in Wisconsin and Michigan have allocated to Bitcoin ETFs.',
    source: 'rag_knowledge_base',
    category: 'institutional'
  },
  {
    title: 'DeFi Protocol Risk Taxonomy',
    content: 'Major DeFi risk categories: Smart contract exploits (over $3B lost in 2022-2023), Oracle manipulation attacks, governance attacks via flash loans, impermanent loss in AMM liquidity provision, bridge exploits (Wormhole, Ronin), and MEV extraction reducing user trade execution quality. Best practices include multi-sig governance, time-locked upgrades, and formal verification.',
    source: 'rag_knowledge_base',
    category: 'risk'
  },
  {
    title: 'Crypto Market Microstructure',
    content: 'Binance maintains 40-50% of global spot trading volume. CEX vs DEX volume ratio approximately 85:15. Crypto market operates 24/7 with highest volatility during US market overlap (13:30-21:00 UTC). Weekend liquidity typically 30-40% lower than weekday. Funding rates on perpetual futures serve as key sentiment indicators — sustained positive rates above 0.05% indicate overleveraged longs.',
    source: 'rag_knowledge_base',
    category: 'market_structure'
  }
];

return documents.map(doc => ({
  json: doc
}));

const embResp = $('Gemini Embed Document').first().json;
const doc = $('Load Knowledge Documents').first().json;

const embedding = embResp?.embedding?.values || [];

if (embedding.length === 0) {
  throw new Error('Failed to generate embedding for: ' + doc.title);
}

return [{
  json: {
    content: doc.title + ': ' + doc.content,
    metadata: {
      source: doc.source || 'unknown',
      category: doc.category || 'general',
      title: doc.title,
      ingested_at: new Date().toISOString()
    },
    embedding: embedding
  }
}];

const results = $('Upsert to Supabase rag_memory').all();

let successes = 0;
let failures = 0;
let errors = [];

for (const item of results) {
  if (item.json?.id) {
    successes++;
  } else if (Array.isArray(item.json) && item.json[0]?.id) {
    successes++;
  } else {
    failures++;
    errors.push(JSON.stringify(item.json).slice(0, 200));
  }
}

return [{
  json: {
    total_processed: results.length,
    successes,
    failures,
    errors: errors.slice(0, 5),
    timestamp: new Date().toISOString(),
    summary: `RAG Ingestion Complete: ${successes} docs ingested, ${failures} failures.`
  }
}];
